#!/usr/bin/env python3
"""Custodia, identidad y campaña U4: solo SELECT y comprobación de archivos privados por streaming."""
import argparse,json,hashlib,subprocess
from pathlib import Path
p=argparse.ArgumentParser(description=__doc__);p.add_argument('private',type=Path);p.add_argument('--evidencias',type=Path,required=True);a=p.parse_args();private=a.private.resolve();out=a.evidencias.resolve()
props=dict(l.split('=',1) for l in (private/'application.properties').read_text().splitlines() if '=' in l and not l.startswith('#'))
if not(props.get('server.address')=='127.0.0.1' and props.get('server.port')=='20443' and '/robust_inst_formulario_lab?' in props.get('institucional.db.url','')):p.error('Solo laboratorio institucional aislado')
def query(sql):
 r=subprocess.run(['docker','exec','-i','siger-mysql-lab-mysql-1','mysql','--defaults-extra-file=/run/secrets/root.cnf','--default-character-set=utf8mb4','-N','--raw'],input=sql,capture_output=True,text=True)
 if r.returncode:raise SystemExit('Consulta privada no completada; diagnóstico SQL omitido')
 return [json.loads(line) for line in r.stdout.splitlines()]
old=json.loads((out/'baseline-registro.json').read_text())
current=query("SELECT JSON_OBJECT('id',comunicacion_id,'huella',SHA2(CONCAT_WS('|',source,COALESCE(operacion_id,''),numero,registrada_ms,canal,content_hash,provenance_hash,folio_prefix,folio_width),256)) FROM robust_inst_formulario_lab.communication_registry ORDER BY numero;")
mapped={r['id']:r['huella'] for r in current};assert all(mapped[r['id']]==r['huella'] for r in old)
public=query("SELECT JSON_OBJECT('id',i.id,'immutable',SHA2(CONCAT(i.body,i.receipt,c.comunicacion_id,c.numero,c.registrada_ms,c.canal,c.content_hash,c.provenance_hash),256),'ack_pending',i.ack_pending) FROM robust_inst_formulario_lab.institutional_inbox i JOIN robust_inst_formulario_lab.communication_registry c ON c.source=i.source AND c.operacion_id=i.id ORDER BY i.id;")
assert public==json.loads((out.parent/'documental/baseline-custodia.json').read_text()) and all(not r['ack_pending'] for r in public)
docs=query("SELECT JSON_OBJECT('key',storage_key,'size',size_bytes,'sha',sha256,'origin',origin) FROM robust_inst_formulario_lab.institution_document;")
pages=query("SELECT JSON_OBJECT('key',storage_key,'size',size_bytes,'sha',sha256) FROM robust_inst_formulario_lab.document_page;")
for d in docs+pages:
 file=private/'archivo/objects'/(d['key']+'.bin');assert file.resolve().is_relative_to(private/'archivo/objects') and not file.is_symlink() and file.stat().st_size==d['size']
 with file.open('rb') as f:assert hashlib.file_digest(f,'sha256').hexdigest()==d['sha']
counts=query("SELECT JSON_OBJECT('migraciones',(SELECT COUNT(*) FROM robust_inst_formulario_lab.flyway_schema_history WHERE success=1),'erroresMigracion',(SELECT COUNT(*) FROM robust_inst_formulario_lab.flyway_schema_history WHERE success=0),'comunicaciones',(SELECT COUNT(*) FROM robust_inst_formulario_lab.communication_registry),'folios',(SELECT COUNT(DISTINCT numero) FROM robust_inst_formulario_lab.communication_registry),'casos',(SELECT COUNT(*) FROM robust_inst_formulario_lab.core_case),'requerimientos',(SELECT COUNT(*) FROM robust_inst_formulario_lab.core_requirement),'tareas',(SELECT COUNT(*) FROM robust_inst_formulario_lab.institution_task),'tareasImpuestas',(SELECT COUNT(*) FROM robust_inst_formulario_lab.institution_task WHERE creator_id<>responsible_id),'tareasSinCaso',(SELECT COUNT(*) FROM robust_inst_formulario_lab.institution_task WHERE resource_type<>'CASO' OR resource_id IS NULL),'notificaciones',(SELECT COUNT(*) FROM robust_inst_formulario_lab.institution_notification),'intentosCorreo',(SELECT COUNT(*) FROM robust_inst_formulario_lab.mail_attempt),'aceptadosGraph',(SELECT COUNT(*) FROM robust_inst_formulario_lab.mail_attempt WHERE state='ACCEPTED_BY_GRAPH' AND http_status=202),'confirmadosUsuario',(SELECT COUNT(*) FROM robust_inst_formulario_lab.notification_outbox WHERE human_state='CONFIRMADA_POR_USUARIO'),'destinosCorreoNoAutorizados',(SELECT COUNT(*) FROM robust_inst_formulario_lab.mail_attempt WHERE resolved_email<>'nexbyte.proveedor@defensorianinez.cl'),'bloqueadosAllowlist',(SELECT COUNT(*) FROM robust_inst_formulario_lab.notification_outbox WHERE state='BLOQUEADO_ALLOWLIST'),'cuentasNexbyte',(SELECT COUNT(*) FROM robust_inst_formulario_lab.staff_account WHERE username='nexbyte'),'rolesNexbyte',(SELECT COUNT(DISTINCT a.role_code) FROM robust_inst_formulario_lab.staff_assignment a JOIN robust_inst_formulario_lab.staff_account s ON s.actor_id=a.actor_id WHERE s.username='nexbyte' AND a.revoked_ms IS NULL),'enviosCampana',(SELECT sends_started FROM robust_inst_formulario_lab.mail_campaign WHERE id='u4_20261025_v1'));")[0]
assert counts['migraciones']==12 and counts['erroresMigracion']==0 and counts['comunicaciones']==counts['folios']==11
assert counts['casos']==5 and counts['requerimientos']==3 and counts['tareas']>=1 and counts['tareasImpuestas']==counts['tareasSinCaso']==0
assert counts['cuentasNexbyte']==1 and counts['rolesNexbyte']==7 and counts['intentosCorreo']==counts['aceptadosGraph']==counts['confirmadosUsuario']==counts['enviosCampana']==4 and counts['destinosCorreoNoAutorizados']==0
emails=query("SELECT JSON_OBJECT('evento',CONCAT(n.stream_code,':',n.event_key),'notificacion',n.id,'categoria',n.category,'destinatarioId',n.recipient_id,'direccionResuelta',m.resolved_email,'fechaIntentoMs',m.started_ms,'fechaFinMs',m.finished_ms,'estadoTransporte',m.state,'etapa',m.stage_code,'http',m.http_status,'requestIdRemoto',m.remote_request_id,'correlacion',o.correlation_id,'confirmacionHumana',o.human_state,'confirmadaPor',o.confirmed_by,'confirmadaEnMs',o.confirmed_ms) FROM robust_inst_formulario_lab.mail_attempt m JOIN robust_inst_formulario_lab.institution_notification n ON n.id=m.notification_id JOIN robust_inst_formulario_lab.notification_outbox o ON o.notification_id=n.id ORDER BY m.started_ms;")
assert len(emails)==4 and all(e['confirmadaPor']==e['destinatarioId'] for e in emails)
for file in (private/'notificaciones/graph-client-secret.txt',private/'notificaciones/allowlist.txt',private/'nexbyte-cuenta.json'):assert file.stat().st_mode&0o777==0o600
assert not [f for f in (private/'archivo/tmp').iterdir() if f.is_file()]
result={'comunicacionesPreviasConservadas':len(old),'custodiaPublicaConservada':len(public),'originalesCiudadanos':sum(d['origin']=='INGRESO_CIUDADANO' for d in docs),'originalesGestion':sum(d['origin']=='GESTION_INSTITUCIONAL' for d in docs),'paginasDerivadas':len(pages),'integridadOriginalesYDerivadas':True,'ackPendientes':0,'temporales':0,'secretosPrivados0600':True,**counts}
(out/'custodia-verificada.json').write_text(json.dumps(result,indent=2));(out/'envios-sanitizados-sql.json').write_text(json.dumps(emails,indent=2))
print(json.dumps(result))
